        'sales-orders':           ['salesOrders', 'customers', 'inventoryItems'],
        'sales-invoices':         ['salesInvoices', 'customers', 'inventoryItems', 'bankAccounts'],
        'sales-payments':         ['salesInvoices', 'customers', 'accounts', 'bankAccounts'],
