        // ── Purchase (Pembelian) ──────────────────────────────────────────────
        'purchase-dashboard':         ['purchaseOrders', 'purchaseInvoices', 'suppliers', 'purchaseRFQs'],
        'purchase-master-items':      ['inventoryItems'],
