window.openApp = (appName) => {
    window.activeDepartment = appName;
    localStorage.setItem('unityerp_active_dept', appName);

    // Expand the correct group in sidebar
    const groups = document.querySelectorAll('.nav-group');
    groups.forEach(group => {
        if (group.id === appName + '-group') {
            group.classList.remove('hidden');
        } else {
            group.classList.add('hidden');
        }
    });

    // Default routes per app
    if (appName === 'penjualan') navigateTo('sales-dashboard');
    else if (appName === 'pembelian') navigateTo('purchase-dashboard');
    else if (appName === 'logistik') navigateTo('inventory-dashboard');
    else if (appName === 'produksi') navigateTo('production-dashboard');
    else if (appName === 'finance') navigateTo('finance-dashboard');
    else if (appName === 'pengaturan') navigateTo('settings-dashboard');
};

// --- Modals ---
function showModal(title, bodyHtml, footerHtml, size = 'md') {
    const modalContainer = document.getElementById('modal-container');
    const sizeClasses = {
        'sm': 'max-w-md',
        'md': 'max-w-2xl',
        'lg': 'max-w-4xl',
        'xl': 'max-w-6xl',
        'full': 'max-w-none w-screen h-screen rounded-none m-0 pt-0'
    };
    const sizeClass = sizeClasses[size] || sizeClasses['md'];

    // Track modal state
    window._isModalOpen = true;
    
    // Save current breadcrumb to restore later
    const pageTitleEl = document.getElementById('pageTitle');
    window._previousBreadcrumbTitle = pageTitleEl ? pageTitleEl.innerText : '';
    
    // Update breadcrumb to show modal title
    const currentPath = BREADCRUMB_MAP[window._currentView] || [];
    renderBreadcrumb([...currentPath, title]);

    modalContainer.innerHTML = `
        <div class="fixed inset-0 top-16 bg-slate-900/40 backdrop-blur-[2px] flex items-center justify-center z-[150] ${size === 'xl' ? '' : 'p-4 sm:p-6'} animate-fade-in" id="modal-backdrop">
        <div class="bg-white shadow-2xl w-full ${sizeClass} flex flex-col ${size === 'xl' ? 'h-full border-0' : 'rounded-2xl max-h-[calc(100vh-120px)] border border-slate-200'} animate-slide-up overflow-hidden">
            <div class="flex justify-between items-center p-4 sm:px-6 sm:py-5 border-b border-gray-100 shrink-0">
                <h3 class="text-xl font-bold text-gray-800 tracking-tight flex items-center gap-3">
                    <span class="w-2 h-8 bg-blue-600 rounded-full"></span>
                    ${title}
                </h3>
                <button class="w-10 h-10 flex items-center justify-center rounded-full text-slate-400 hover:bg-slate-100 hover:text-slate-600 transition-all" onclick="closeModal()">
                    <i class="fas fa-times text-lg"></i>
                </button>
            </div>
            <div class="p-4 sm:p-8 overflow-y-auto flex-1 bg-white">
                ${bodyHtml}
            </div>
            <div class="px-4 py-4 sm:px-8 sm:flex sm:flex-row-reverse bg-slate-50 border-t border-slate-100 shrink-0 gap-3">
                ${footerHtml}
            </div>
        </div>
        </div>
        `;
}

function closeModal() {
    window._isModalOpen = false;
    document.getElementById('modal-container').innerHTML = '';
    
    // Restore breadcrumb
    if (window._currentView) {
        const path = BREADCRUMB_MAP[window._currentView] || [window._currentView.replace(/-/g, ' ').replace(/\b\w/g, l => l.toUpperCase())];
        renderBreadcrumb(path);
    }
}

// --- Toasts (Notifications) ---
function showToast(message, type = 'success') {
    const container = document.getElementById('toast-container');
    const toast = document.createElement('div');
    const bgColor = type === 'success' ? 'bg-green-50 border-green-200' : (type === 'info' ? 'bg-blue-50 border-blue-200' : 'bg-red-50 border-red-200');
    const textColor = type === 'success' ? 'text-green-800' : (type === 'info' ? 'text-blue-800' : 'text-red-800');
    const icon = type === 'success' ? 'fa-check-circle text-green-500' : (type === 'info' ? 'fa-info-circle text-blue-500' : 'fa-exclamation-circle text-red-500');

    toast.className = `flex items-center w-full max-w-xs p-4 mb-4 text-gray-500 ${bgColor} border rounded-lg shadow animate-slide-left`;
    toast.innerHTML = `
        <div class="inline-flex items-center justify-center flex-shrink-0 w-8 h-8 rounded-lg">
            <i class="fas ${icon}"></i>
        </div>
        <div class="ml-3 text-sm font-normal ${textColor}">${message}</div>
        <button type="button" class="ml-auto -mx-1.5 -my-1.5 bg-transparent text-gray-400 hover:text-gray-900 rounded-lg p-1.5 inline-flex h-8 w-8 transition-colors" onclick="this.parentElement.remove()">
            <span class="sr-only">Close</span>
            <i class="fas fa-times"></i>
        </button>
    `;
    container.appendChild(toast);
    setTimeout(() => toast.remove(), 4000);
}

// --- Custom Modern Confirmation Dialog ---
window.showConfirmDialog = function(options = {}) {
    let title = options.title || 'Konfirmasi Tindakan';
    let message = options.message || 'Apakah Anda yakin ingin melanjutkan?';
    let confirmText = options.confirmText || 'Ya, Lanjutkan';
    let cancelText = options.cancelText || 'Batal';
    let type = options.type || 'danger'; // 'danger' | 'warning' | 'primary' | 'info'
    let icon = options.icon;

    if (!icon) {
        if (type === 'danger') icon = 'fa-trash-alt';
        else if (type === 'warning') icon = 'fa-exclamation-triangle';
        else if (type === 'primary') icon = 'fa-check-circle';
        else icon = 'fa-info-circle';
    }

    const typeClasses = {
        danger: {
            iconBg: 'bg-rose-50 border-rose-100 text-rose-600',
            confirmBtn: 'bg-rose-600 hover:bg-rose-700 text-white shadow-rose-600/20',
        },
        warning: {
            iconBg: 'bg-amber-50 border-amber-100 text-amber-600',
            confirmBtn: 'bg-amber-500 hover:bg-amber-600 text-white shadow-amber-500/20',
        },
        primary: {
            iconBg: 'bg-blue-50 border-blue-100 text-blue-600',
            confirmBtn: 'bg-blue-600 hover:bg-blue-700 text-white shadow-blue-600/20',
        },
        info: {
            iconBg: 'bg-indigo-50 border-indigo-100 text-indigo-600',
            confirmBtn: 'bg-indigo-600 hover:bg-indigo-700 text-white shadow-indigo-600/20',
        }
    };

    const cfg = typeClasses[type] || typeClasses.danger;

    return new Promise((resolve) => {
        // Remove existing modal if any
        const existing = document.getElementById('custom-confirm-modal');
        if (existing) existing.remove();

        const dialogContainer = document.createElement('div');
        dialogContainer.id = 'custom-confirm-modal';
        dialogContainer.className = 'fixed inset-0 z-[9999] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in duration-200 select-none';
        
        dialogContainer.innerHTML = `
            <div class="bg-white rounded-3xl shadow-2xl border border-slate-100 max-w-md w-full p-6 sm:p-7 transform transition-all animate-in zoom-in-95 duration-200">
                <div class="flex items-start gap-4">
                    <div class="w-12 h-12 rounded-2xl ${cfg.iconBg} border flex items-center justify-center shrink-0 shadow-sm">
                        <i class="fas ${icon} text-lg"></i>
                    </div>
                    <div class="flex-1 min-w-0 pt-0.5">
                        <h3 class="text-base font-black text-slate-800 tracking-tight leading-snug">${title}</h3>
                        <p class="text-xs font-medium text-slate-500 mt-2 leading-relaxed whitespace-pre-line">${message}</p>
                    </div>
                </div>
                <div class="mt-6 pt-4 border-t border-slate-100 flex items-center justify-end gap-2.5">
                    <button id="custom-confirm-cancel-btn" type="button" 
                        class="px-4 py-2 rounded-xl border border-slate-200 hover:bg-slate-50 text-slate-600 font-bold text-xs transition-all active:scale-95 cursor-pointer">
                        ${cancelText}
                    </button>
                    <button id="custom-confirm-ok-btn" type="button" 
                        class="px-4 py-2 rounded-xl ${cfg.confirmBtn} font-bold text-xs shadow-lg transition-all active:scale-95 flex items-center gap-2 cursor-pointer">
                        ${confirmText}
                    </button>
                </div>
            </div>
        `;

        const cleanup = (result) => {
            document.removeEventListener('keydown', handleKeyDown);
            dialogContainer.classList.remove('fade-in');
            dialogContainer.classList.add('fade-out');
            setTimeout(() => {
                if (dialogContainer.parentNode) dialogContainer.parentNode.removeChild(dialogContainer);
            }, 120);
            resolve(result);
        };

        dialogContainer.querySelector('#custom-confirm-cancel-btn').onclick = () => cleanup(false);
        dialogContainer.querySelector('#custom-confirm-ok-btn').onclick = () => cleanup(true);

        dialogContainer.onclick = (e) => {
            if (e.target === dialogContainer) cleanup(false);
        };

        const handleKeyDown = (e) => {
            if (e.key === 'Escape') {
                cleanup(false);
            } else if (e.key === 'Enter') {
                cleanup(true);
            }
        };
        document.addEventListener('keydown', handleKeyDown);

        document.body.appendChild(dialogContainer);
        const okBtn = dialogContainer.querySelector('#custom-confirm-ok-btn');
        if (okBtn) okBtn.focus();
    });
};

window.customConfirm = async (messageOrOptions, fallbackTitle) => {
    if (typeof messageOrOptions === 'object') {
        return window.showConfirmDialog(messageOrOptions);
    }
    const msg = String(messageOrOptions || '');
    const isDelete = /hapus|delete|remove|hilang/i.test(msg);
    const isCancel = /batal|cancel/i.test(msg);
    const isWarn = /peringatan|warning|perhatian/i.test(msg);
    
    let type = 'danger';
    let title = fallbackTitle || (isDelete ? 'Konfirmasi Hapus' : (isCancel ? 'Konfirmasi Pembatalan' : (isWarn ? 'Peringatan Penting' : 'Konfirmasi Tindakan')));
    let confirmText = isDelete ? 'Hapus' : (isCancel ? 'Batalkan' : 'Ya, Lanjutkan');
    let icon = isDelete ? 'fa-trash-alt' : (isCancel ? 'fa-ban' : 'fa-exclamation-triangle');

    return window.showConfirmDialog({
        title,
        message: msg,
        type: isWarn ? 'warning' : type,
        confirmText,
        cancelText: 'Kembali',
        icon
    });
};

// --- Formatting Helpers ---
window.formatCurrency = (amount) => {
    const num = parseFloat(amount) || 0;
    // Format with Indonesian locale: dots as thousand separator, comma as decimal
    const formatted = new Intl.NumberFormat('id-ID', {
        minimumFractionDigits: 0,
        maximumFractionDigits: 0
    }).format(Math.round(num));
    return `Rp ${formatted}`;
};

// Format plain numbers with thousand separator dots (e.g. 1000 â†’ 1.000)
window.formatNumber = (num, decimals = 0) => {
    const n = parseFloat(num) || 0;
    return new Intl.NumberFormat('id-ID', {
        minimumFractionDigits: decimals,
        maximumFractionDigits: decimals
    }).format(n);
};

window.formatDate = (isoString) => {
    if (!isoString) return '-';
    const date = new Date(isoString);
    const locale = CONFIG.language === 'en' ? 'en-US' : 'id-ID';

    // Simplistic mapping for common formats
    const options = { hour: '2-digit', minute: '2-digit' };
    if (CONFIG.dateFormat === 'YYYY-MM-DD') {
        const y = date.getFullYear();
        const m = String(date.getMonth() + 1).padStart(2, '0');
        const d = String(date.getDate()).padStart(2, '0');
        return `${y}-${m}-${d} ${date.toLocaleTimeString(locale, options)}`;
    } else if (CONFIG.dateFormat === 'MM/DD/YYYY') {
        return date.toLocaleDateString('en-US') + ' ' + date.toLocaleTimeString(locale, options);
    } else {
        // Default DD/MM/YYYY
        return date.toLocaleDateString('id-ID', { day: '2-digit', month: '2-digit', year: 'numeric' }) + ' ' + date.toLocaleTimeString(locale, options);
    }
};

