window.showPOReceiptHistoryModal = (poId) => {
    const po = db.findById('purchaseOrders', poId);
    if (!po) return;

    let receipts = po.receipts || [];
    if (typeof receipts === 'string') {
        try {
            receipts = JSON.parse(receipts);
        } catch (e) {
            receipts = [];
        }
    }

    const isAdmin = typeof isCurrentUserAdmin === 'function' ? isCurrentUserAdmin() : false;

    let bodyHtml = '';
    if (receipts && receipts.length > 0) {
        const cards = receipts.map((receipt, idx) => {
            const dateStr = receipt.date ? receipt.date.split('T')[0] : '';
            const sjStr = receipt.suratJalan || receipt.sjNumber || '-';
            const notesStr = receipt.notes || receipt.receiver || '-';
            const npbStr = receipt.npbNumber || receipt.npb || '-';
            
            const rows = (receipt.items || []).map((item, i) => `
                <tr class="text-xs text-slate-700 hover:bg-slate-50/30 transition-colors">
                    <td class="py-3 px-5 text-center font-bold text-slate-400 border-b border-slate-100">${i + 1}</td>
                    <td class="py-3 px-5 font-black uppercase text-slate-800 border-b border-slate-100">${item.prodText || item.name || '-'}</td>
                    <td class="py-3 px-5 text-center font-black text-slate-900 border-b border-slate-100">${(item.receivedQty || item.qty || 0).toLocaleString('id-ID')}</td>
                    <td class="py-3 px-5 text-center font-bold text-slate-500 uppercase border-b border-slate-100">${item.unit || 'PCS'}</td>
                </tr>
            `).join('');

            return `
                <div class="bg-white rounded-3xl border border-slate-200/60 shadow-sm p-6 mb-6 transition-all hover:shadow-md relative overflow-hidden group">
                    <div class="flex flex-wrap items-center justify-between gap-4 border-b border-slate-100 pb-4 mb-4">
                        <div class="flex items-center gap-3">
                            <span class="px-3 py-1 bg-slate-900 text-white rounded-lg text-[9px] font-black uppercase tracking-widest">
                                Penerimaan ke-${idx + 1}
                            </span>
                            <span class="text-xs font-mono font-bold text-blue-600 bg-blue-50 px-3 py-1 rounded-lg border border-blue-100">
                                ${npbStr}
                            </span>
                        </div>
                        <div class="flex items-center gap-2">
                            <button onclick="printNPB('${po.id}', '${receipt.id}')"
                                class="px-5 py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl text-[9px] font-black uppercase tracking-widest transition-all flex items-center gap-2 active:scale-95 shadow-md shadow-emerald-500/10 hover:shadow-emerald-500/20">
                                <i class="fas fa-print text-[10px]"></i> Cetak NPB
                            </button>
                            ${isAdmin ? `
                            <button onclick="window.deletePOReceipt('${po.id}', '${receipt.id}', '${npbStr}')"
                                class="px-4 py-2.5 bg-rose-50 hover:bg-rose-600 text-rose-600 hover:text-white border border-rose-200 hover:border-rose-600 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all flex items-center gap-1.5 active:scale-95 shadow-sm cursor-pointer"
                                title="Hapus / Batalkan Penerimaan Ini (Khusus Administrator)">
                                <i class="fas fa-trash-alt text-[10px]"></i> Hapus NPB
                            </button>
                            ` : ''}
                        </div>
                    </div>
                    
                    <div class="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-4 bg-slate-50/50 p-4 rounded-2xl border border-slate-100/50">
                        <div>
                            <span class="block text-[8px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">Tanggal Terima</span>
                            <span class="text-xs font-black text-slate-700">${dateStr}</span>
                        </div>
                        <div>
                            <span class="block text-[8px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">No. SJ Supplier</span>
                            <span class="text-xs font-black text-slate-700 uppercase">${sjStr}</span>
                        </div>
                        <div>
                            <span class="block text-[8px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">Nama Penerima / Keterangan</span>
                            <span class="text-xs font-black text-slate-700 uppercase">${notesStr}</span>
                        </div>
                    </div>
                    
                    <div class="mt-4 bg-white rounded-2xl border border-slate-150 overflow-hidden shadow-sm">
                        <table class="w-full text-left border-collapse">
                            <thead>
                                <tr class="bg-slate-50 border-b border-slate-150 text-[9px] font-black text-slate-400 uppercase tracking-wider">
                                    <th class="py-3 px-5 w-12 text-center">No</th>
                                    <th class="py-3 px-5">Deskripsi Barang</th>
                                    <th class="py-3 px-5 text-center w-32">Qty Diterima</th>
                                    <th class="py-3 px-5 text-center w-24">Satuan</th>
                                </tr>
                            </thead>
                            <tbody>
                                ${rows}
                            </tbody>
                        </table>
                    </div>
                </div>
            `;
        }).join('');

        bodyHtml = `
            <div class="space-y-4">
                <p class="text-xs text-slate-450 font-bold uppercase tracking-wider mb-4">Daftar Penerimaan Parsial & Nota Penerimaan Barang (NPB) untuk PO ${po.poNumber}</p>
                <div class="max-h-[60vh] overflow-y-auto pr-2 custom-scrollbar">
                    ${cards}
                </div>
            </div>
        `;
    } else {
        const isAdmin = typeof isCurrentUserAdmin === 'function' ? isCurrentUserAdmin() : false;
        bodyHtml = `
            <div class="p-8 text-center text-slate-400 font-bold uppercase tracking-wider space-y-3">
                <i class="fas fa-info-circle text-3xl mb-1 text-slate-300"></i>
                <p class="text-xs">Belum ada riwayat penerimaan barang untuk PO ${po.poNumber}</p>
                ${isAdmin && po.status === 'RECEIVED' ? `
                    <div>
                        <button onclick="reopenPOForReceiving('${po.id}')" class="mt-2 px-5 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-xs font-black uppercase tracking-widest shadow-md transition-all active:scale-95 inline-flex items-center gap-2">
                            <i class="fas fa-truck-loading"></i> Pindahkan ke Antrian Gudang (Terima Ulang)
                        </button>
                    </div>
                ` : ''}
            </div>
        `;
    }

    showModal(`Riwayat Penerimaan - ${po.poNumber}`, bodyHtml, `
        <button onclick="closeModal()" class="px-6 py-2.5 bg-slate-100 text-slate-500 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-slate-200 transition-all">TUTUP</button>
    `, 'lg');
};

window.reopenPOForReceiving = async function(poId) {
    const isAdmin = typeof isCurrentUserAdmin === 'function' ? isCurrentUserAdmin() : false;
    if (!isAdmin) {
        showToast('Akses ditolak: Hanya Administrator yang dapat membuka ulang penerimaan.', 'error');
        return;
    }

    const po = db.findById('purchaseOrders', poId);
    if (!po) return;

    const confirmed = await window.showConfirmDialog({
        title: 'Buka Penerimaan Ulang (Antrian Gudang)',
        message: `Pindahkan <strong>${po.poNumber}</strong> kembali ke <strong>Antrian Gudang</strong> untuk dilakukan penerimaan barang ulang?<br><br>
                  <span class="text-xs text-slate-500">Status PO akan diubah ke <strong>APPROVED</strong> agar tim gudang dapat memproses tombol Terima Barang.</span>`,
        confirmText: 'Ya, Pindahkan ke Antrian Gudang',
        cancelText: 'Batal',
        type: 'warning',
        icon: 'fa-truck-loading'
    });
    if (!confirmed) return;

    let items = po.items || [];
    if (typeof items === 'string') {
        try { items = JSON.parse(items); } catch (e) { items = []; }
    }
    items.forEach(i => { i.receivedQty = 0; });

    await db.update('purchaseOrders', poId, {
        status: 'APPROVED',
        items: items,
        receipts: []
    });

    await db.sync('purchaseOrders');
    if (typeof closeModal === 'function') closeModal();
    showToast(`PO ${po.poNumber} berhasil dipindahkan ke Antrian Gudang!`, 'success');
    window.activeGRTab = 'pending';
    if (typeof renderPurchaseReceiving === 'function') {
        renderPurchaseReceiving();
    }
};

window.deletePOReceipt = async function(poId, receiptId, npbNumber) {
    const isAdmin = typeof isCurrentUserAdmin === 'function' ? isCurrentUserAdmin() : false;
    if (!isAdmin) {
        showToast('Akses ditolak: Hanya Administrator yang dapat menghapus penerimaan barang.', 'error');
        return;
    }

    const confirmed = await window.showConfirmDialog({
        title: 'Hapus Penerimaan Barang (NPB)',
        message: `Apakah Anda yakin ingin menghapus penerimaan <strong>${npbNumber || 'ini'}</strong> dari PO?<br><br>
                  <span class="text-xs text-rose-600 font-bold block mb-1">Dampak Penghapusan:</span>
                  <ul class="text-xs text-slate-500 list-disc list-inside space-y-1">
                    <li>NPB akan dihapus permanen dari riwayat penerimaan PO.</li>
                    <li>Kuantitas barang yang diterima pada item PO akan dikurangi kembali.</li>
                    <li>Status PO akan dihitung ulang secara otomatis.</li>
                    <li>Antrean tagihan di menu Purchase Invoice (Belum Dibuat Invoice) akan diperbarui.</li>
                  </ul>`,
        confirmText: 'Ya, Hapus Penerimaan',
        cancelText: 'Batal',
        type: 'danger',
        icon: 'fa-trash-alt'
    });
    if (!confirmed) return;

    try {
        showToast('Menghapus penerimaan barang...', 'info');
        let res = null;

        // Try dedicated backend API if available
        if (window.api && typeof window.api.deletePOReceipt === 'function') {
            try {
                res = await window.api.deletePOReceipt(poId, receiptId);
            } catch (apiErr) {
                console.warn('API deletePOReceipt failed, falling back to local db update:', apiErr);
            }
        }

        // Optimistic and fallback client update
        const po = db.findById('purchaseOrders', poId);
        if (po) {
            let receipts = po.receipts || [];
            if (typeof receipts === 'string') {
                try { receipts = JSON.parse(receipts); } catch (e) { receipts = []; }
            }
            let poItems = po.items || [];
            if (typeof poItems === 'string') {
                try { poItems = JSON.parse(poItems); } catch (e) { poItems = []; }
            }

            const targetIdx = receipts.findIndex(r => r.id === receiptId || r.npbNumber === receiptId || r.npb === receiptId || (npbNumber && (r.npbNumber === npbNumber || r.npb === npbNumber)));
            if (targetIdx > -1) {
                // Remove the receipt from receipts array
                receipts.splice(targetIdx, 1);

                // Recalculate receivedQty for all PO items from the remaining receipts
                poItems.forEach(item => { item.receivedQty = 0; });
                receipts.forEach(rcpt => {
                    (rcpt.items || []).forEach(rItem => {
                        const itemQty = parseFloat(rItem.qty || rItem.receivedQty || 0);
                        if (itemQty <= 0) return;

                        let matched = null;
                        if (rItem.index !== undefined && poItems[rItem.index] && (
                            !rItem.prodText || 
                            poItems[rItem.index].prodText === rItem.prodText ||
                            poItems[rItem.index].itemName === rItem.prodText
                        )) {
                            matched = poItems[rItem.index];
                        } else {
                            matched = poItems.find(pi => 
                                (rItem.inventoryItemId && (pi.inventoryItemId === rItem.inventoryItemId || pi.id === rItem.inventoryItemId)) ||
                                (pi.prodText && rItem.prodText && pi.prodText.toLowerCase().replace(/\s+/g, '') === rItem.prodText.toLowerCase().replace(/\s+/g, '')) ||
                                (pi.itemName && rItem.prodText && pi.itemName.toLowerCase().replace(/\s+/g, '') === rItem.prodText.toLowerCase().replace(/\s+/g, ''))
                            );
                        }

                        if (!matched && poItems.length === 1) {
                            matched = poItems[0];
                        }

                        if (matched) {
                            matched.receivedQty = (parseFloat(matched.receivedQty || 0) + itemQty);
                        }
                    });
                });

                let sumReceivedAll = 0;
                let sumTargetAll = 0;
                poItems.forEach(item => {
                    sumTargetAll += parseFloat(item.qty || 0);
                    sumReceivedAll += parseFloat(item.receivedQty || 0);
                });

                let newStatus = 'APPROVED';
                if (sumReceivedAll >= sumTargetAll && sumTargetAll > 0) {
                    newStatus = 'RECEIVED';
                } else if (sumReceivedAll > 0) {
                    newStatus = 'PARTIALLY RECEIVED';
                } else {
                    newStatus = 'APPROVED';
                }

                await db.update('purchaseOrders', po.id, {
                    items: poItems,
                    receipts: receipts,
                    status: newStatus
                });
            }
        }

        // Sync local cache with backend
        await Promise.all([
            db.sync('purchaseOrders'),
            db.sync('inventoryItems'),
            db.sync('stockTransactions')
        ]);

        showToast(res?.message || `Penerimaan ${npbNumber || ''} berhasil dihapus!`, 'success');

        // Re-render modal if still open
        const updatedPO = db.findById('purchaseOrders', poId);
        let updatedReceipts = updatedPO?.receipts || [];
        if (typeof updatedReceipts === 'string') {
            try { updatedReceipts = JSON.parse(updatedReceipts); } catch (e) { updatedReceipts = []; }
        }
        if (updatedReceipts && updatedReceipts.length > 0) {
            window.showPOReceiptHistoryModal(poId);
        } else {
            closeModal();
        }

        // Refresh views
        if (typeof renderPurchaseReceiving === 'function' && document.getElementById('pageTitle')?.innerText.includes('Received')) {
            renderPurchaseReceiving();
        } else if (typeof _renderPurchaseInvoicesList === 'function' && document.getElementById('pageTitle')?.innerText.includes('Invoice')) {
            _renderPurchaseInvoicesList();
        } else if (typeof renderPurchaseOrders === 'function') {
            renderPurchaseOrders();
        }
    } catch (err) {
        showToast(err.message || 'Gagal menghapus penerimaan', 'error');
    }
};

